1	import { useState, useEffect, useRef, type CSSProperties, Component, type ReactNode } from "react";
2	import { useParams, useLocation, useSearch } from "wouter";
3	import { useQuery } from "@tanstack/react-query";
4	import { apiRequest } from "@/lib/queryClient";
5	import { Loader2, CheckCircle, XCircle } from "lucide-react";
6	import taptLogo from "@assets/IMG_6592_1755070818452.png";
7	import googlePayLogo from "@assets/Google_Pay_Logo.svg_1773556576322.png";
8	// Window augmentations are declared centrally in client/src/global.d.ts.
9	
10	// ── Error boundary — catches any render crash and shows a safe fallback ──
11	class CheckoutErrorBoundary extends Component<{ children: ReactNode }, { hasError: boolean }> {
12	  constructor(props: { children: ReactNode }) {
13	    super(props);
14	    this.state = { hasError: false };
15	  }
16	  static getDerivedStateFromError() { return { hasError: true }; }
17	  componentDidCatch(err: Error) { console.error("[Checkout] Render error:", err); }
18	  render() {
19	    if (this.state.hasError) {
20	      return (
21	        <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: "#f0f4ff", padding: 24 }}>
22	          <div style={{ background: "#fff", borderRadius: 24, padding: 32, textAlign: "center", maxWidth: 320 }}>
23	            <XCircle size={48} color="#e53e3e" style={{ margin: "0 auto 16px" }} />
24	            <h2 style={{ color: "#e53e3e", fontWeight: 700, marginBottom: 8 }}>Something went wrong</h2>
25	            <p style={{ color: "#666", marginBottom: 20 }}>Please scan the QR code again to restart your payment.</p>
26	            <button
27	              onClick={() => window.history.back()}
28	              style={{ background: "#0055FF", color: "#fff", border: "none", borderRadius: 14, padding: "12px 24px", fontWeight: 600, cursor: "pointer" }}
29	            >
30	              Go back
31	            </button>
32	          </div>
33	        </div>
34	      );
35	    }
36	    return this.props.children;
37	  }
38	}
39	
40	function detectInAppBrowser(): { isInApp: boolean; isAndroid: boolean; isIOS: boolean } {
41	  const ua = navigator.userAgent || "";
42	  const isAndroid = /Android/i.test(ua);
43	  const isIOS = /iPhone|iPad|iPod/i.test(ua);
44	  const isInApp =
45	    /FBAN|FBAV|Instagram|Twitter|Line|WeChat|Snapchat|TikTok|LinkedIn|Pinterest|Tumblr|Reddit|Bytedance/i.test(ua) ||
46	    (isAndroid && /wv\)/i.test(ua)) ||
47	    (/\bMobile\b/.test(ua) && !/Chrome|CriOS|FxiOS|Safari/i.test(ua) && (isAndroid || isIOS));
48	  return { isInApp, isAndroid, isIOS };
49	}
50	
51	function loadScript(src: string): Promise<void> {
52	  return new Promise((resolve, reject) => {
53	    if (document.querySelector(`script[src="${src}"]`)) { resolve(); return; }
54	    const s = document.createElement("script");
55	    s.src = src; s.async = true;
56	    s.onload = () => resolve();
57	    s.onerror = () => reject(new Error(`Failed: ${src}`));
58	    document.head.appendChild(s);
59	  });
60	}
61	
62	// Windcave / PaymentExpress HPP domain patterns.
63	// Covers windcave.com (current) and paymentexpress.com (Windcave's legacy domain
64	// still referenced in some SDK redirect fallbacks).  Also catches any subdomain.
65	const WINDCAVE_HPP_RE = /^https?:\/\/(?:[a-z0-9-]+\.)*(?:windcave|paymentexpress)\.com/i;
66	
67	function CheckoutInner() {
68	  // This page serves two payment sources behind one branded UI:
69	  //   • Retail transactions at /checkout/:transactionId
70	  //   • Property rent/charge invoices at /r/:token
71	  // Only the data source and the three network calls differ; the wallet, 3DS,
72	  // navigation-guard and Hosted Fields machinery below is identical for both.
73	  const { transactionId, token } = useParams<{ transactionId?: string; token?: string }>();
74	  const isInvoice = !!token;
75	  const [, setLocation] = useLocation();
76	  const search = useSearch();
77	  const txId = transactionId ? parseInt(transactionId) : null;
78	  const urlParams = new URLSearchParams(search);
79	  const overrideAmount = urlParams.get("amount");
80	
81	  // Demo/visual build only: there is no Windcave backend, so the card flow is
82	  // short-circuited to the success screen and the Hosted Fields are replaced by
83	  // static demo values. Compile-time constant → tree-shaken from real builds.
84	  const IS_MOCK = import.meta.env.VITE_MOCK === "1";
85	
86	  // Source-specific endpoints — keyed by token for invoices, numeric id for txns.
87	  const sessionEndpoint = isInvoice ? `/api/checkout/${token}/session` : `/api/transactions/${txId}/pay`;
88	  const hfCompleteEndpoint = isInvoice ? `/api/checkout/${token}/hosted-fields-complete` : `/api/transactions/${txId}/hosted-fields-complete`;
89	  const gpayCompleteEndpoint = isInvoice ? `/api/checkout/${token}/googlepay-complete` : `/api/transactions/${txId}/googlepay-complete`;
90	  // Stable identifier for effect deps / guards across both sources.
91	  const payId: string | number | null = isInvoice ? (token ?? null) : txId;
92	
93	  // Invoice split state (no-op for retail transactions).
94	  const [splitChoosing, setSplitChoosing] = useState(false);
95	  const [payerEmail, setPayerEmail] = useState("");
96	  const [splitBusy, setSplitBusy] = useState(false);
97	
98	  const [cardOpen, setCardOpen] = useState(false);
99	  const [applePayAvailable, setApplePayAvailable] = useState(false);
100	  const [googlePayAvailable, setGooglePayAvailable] = useState(false);
101	  const [hfReady, setHfReady] = useState(false);
102	  const [payState, setPayState] = useState<"idle" | "processing" | "success" | "error">("idle");
103	  const [errorMsg, setErrorMsg] = useState("");
104	  const [linkCopied, setLinkCopied] = useState(false);
105	  const inAppEnv = detectInAppBrowser();
106	
107	  const hfController = useRef<any>(null);
108	  const hfReadyRef = useRef(false);
109	  const hfScriptsReady = useRef(false);
110	  const hfInitialised = useRef(false);
111	  const googleClient = useRef<any>(null);
112	  const sessionRef = useRef<any>(null);
113	  const applePayOptions = useRef<any>(null);
114	  const applePaySdkLoaded = useRef(false);
115	  const applePaySdkFailed = useRef(false);
116	  const preSessionRef = useRef<any>(null);
117	  // Incrementing this triggers the pre-session useEffect to create a fresh session
118	  const [preSessionTrigger, setPreSessionTrigger] = useState(0);
119	
120	  // Timers that schedule state updates — tracked so they can be cancelled on
121	  // unmount and never fire against an unmounted component.
122	  const navigateTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
123	  const linkCopiedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
124	  useEffect(() => {
125	    return () => {
126	      if (navigateTimerRef.current) clearTimeout(navigateTimerRef.current);
127	      if (linkCopiedTimerRef.current) clearTimeout(linkCopiedTimerRef.current);
128	    };
129	  }, []);
130	
131	  // Google Pay pre-session — mirrors Apple Pay's approach so the Windcave session
132	  // is ready the moment the user approves Google Pay (no blocking network call).
133	  const googlePreSessionRef = useRef<any>(null);
