const TRADE_INVOICES = buildTradeInvoices();

const TRADE_QUOTES = TRADE_CLIENTS.slice(0, 3).map((c, i) => ({
  id: 8000 + i,
  merchantId: MERCHANT_ID,
  clientProfileId: c.id,
  siteAddress: c.siteAddress,
  token: `quote_${8000 + i}`,
  amountCents: (2400 + i * 900) * 100,
  status: ['sent', 'accepted', 'draft'][i],
  description: `Quote — ${c.notes}`,
  validUntil: iso(now + (14 - i * 3) * DAY),
  createdAt: iso(now - (i + 2) * DAY),
  updatedAt: iso(now - (i + 1) * DAY),
}));

/* ---- retail checkout / customer-payment demo flow --------------------- */
const DEMO_TX = {
  id: 90210,
  merchantId: MERCHANT_ID,
  itemName: 'In-store purchase',
  price: '24.50',
  status: 'completed',
  paymentMethod: 'card_reader',
  windcaveFeeRate: '0.0290',
  platformFeeRate: '0.0020',
  merchantNet: '23.96',
  totalRefunded: '0.00',
  taptStoneId: null,
  isSplit: false,
  splitEnabled: false,
  totalSplits: 1,
  completedSplits: 1,
  createdAt: iso(now),
};

// Resolve a checkout token to the invoice-shape the checkout page expects.
// Falls back to a fresh payable rent invoice so any demo link is payable.
function resolveInvoice(rawToken: string) {
  const inv = [...INVOICES, ...TRADE_INVOICES].find((i: any) => i.token === rawToken);
  if (inv) {
    const isTrade = String(inv.token).startsWith('job_');
    return {
      invoiceId: inv.id,
      merchantId: MERCHANT_ID,
      amountCents: inv.amountCents,
      kind: inv.kind ?? (isTrade ? 'job' : 'rent'),
      description: inv.description,
      vertical: isTrade ? 'trades' : 'property',
      alreadyPaid: inv.status === 'paid' || inv.status === 'paid_external',
      splitEnabled: false,
      splitCount: 0,
      splitPaidCount: 0,
    };
  }
  return {
    invoiceId: 5999,
    merchantId: MERCHANT_ID,
    amountCents: 62000,
    kind: 'rent',
    description: 'Rent — this month',
    vertical: 'property',
    alreadyPaid: false,
    splitEnabled: false,
    splitCount: 0,
    splitPaidCount: 0,
  };
}

const SUBSCRIPTION = {
  plan: 'Growth',
  status: 'active',
  billingFrequency: 'monthly',
  priceMonthly: 0,
  transactionsUsed: TRANSACTIONS.length,
  transactionsLimit: 1000,
  currentPeriodEnd: iso(now + 18 * DAY),
  nextBillingDate: iso(now + 18 * DAY),
  cancelAtPeriodEnd: false,
};

/* ---- route table ------------------------------------------------------ */
// Ordered matchers. First match wins. `re` tested against the URL pathname.
type Handler = (m: RegExpMatchArray, url: URL, init?: RequestInit) => unknown;
const ROUTES: Array<{ re: RegExp; data: Handler }> = [
  { re: /\/api\/auth\/me$/, data: () => ({ user: { id: 1, merchantId: MERCHANT_ID, role: 'merchant', email: MERCHANT.email, onboardingCompleted: true } }) },
  { re: /\/api\/merchants\/\d+\/analytics$/, data: () => ANALYTICS },
  { re: /\/api\/merchants\/\d+\/transactions$/, data: () => TRANSACTIONS },
  { re: /\/api\/merchants\/\d+\/tapt-stones$/, data: () => [{ id: 1, merchantId: MERCHANT_ID, name: 'Front Counter', stoneNumber: 1, isActive: true }] },
  { re: /\/api\/merchants\/\d+\/stock-items$/, data: () => STOCK },
  { re: /\/api\/merchants\/\d+\/(details|business-details)$/, data: () => MERCHANT },
  { re: /\/api\/merchants\/\d+$/, data: () => MERCHANT },
  { re: /\/api\/merchants$/, data: () => [MERCHANT] },
  // Property vertical — specific sub-routes before the list route.
  { re: /\/api\/property\/tenants\/(\d+)\/events/, data: () => [] },
  { re: /\/api\/property\/tenants\/(\d+)(\?|$)/, data: (m) => TENANTS.find((t) => t.id === Number(m[1])) ?? null },
  { re: /\/api\/property\/tenants(\?|$)/, data: () => TENANTS },
  { re: /\/api\/property\/invoices(\?|$)/, data: (_m, url) => { const tid = url.searchParams.get('tenantProfileId'); return tid ? INVOICES.filter((i) => i.tenantProfileId === Number(tid)) : INVOICES; } },
  { re: /\/api\/property\/schedules(\?|$)/, data: () => [] },
  { re: /\/api\/property\/reminder-settings$/, data: () => ({ rentReminderEnabled: true, rentReminderDelayDays: 3, rentReminderIntervalDays: 3, rentReminderMaxCount: 3 }) },
  // Trades vertical — order matters: specific sub-routes before the list route.
  { re: /\/api\/trades\/clients\/(\d+)\/events/, data: () => [] },
  { re: /\/api\/trades\/clients\/(\d+)(\?|$)/, data: (m) => TRADE_CLIENTS.find((c) => c.id === Number(m[1])) ?? null },
  { re: /\/api\/trades\/clients(\?|$)/, data: () => TRADE_CLIENTS },
  { re: /\/api\/trades\/invoices(\?|$)/, data: (_m, url) => { const cid = url.searchParams.get('clientProfileId'); return cid ? TRADE_INVOICES.filter((i) => i.clientProfileId === Number(cid)) : TRADE_INVOICES; } },
  { re: /\/api\/trades\/quotes(\?|$)/, data: () => TRADE_QUOTES },
  { re: /\/api\/trades\/schedules(\?|$)/, data: () => [] },
  { re: /\/api\/trades\/reminder-settings$/, data: () => ({ reminderEnabled: true, reminderDelayDays: 3, reminderIntervalDays: 5, reminderMaxCount: 3 }) },
  // Retail checkout / customer-payment flow.
  { re: /\/api\/merchants\/\d+\/active-transaction/, data: () => ({ ...DEMO_TX, id: 90211, status: 'pending' }) },
  { re: /\/api\/transactions\/(\d+)\/receipt/, data: () => ({}) },
  { re: /\/api\/transactions\/(\d+)$/, data: (m) => ({ ...DEMO_TX, id: Number(m[1]) }) },
  { re: /\/api\/checkout\/resolve\/([^/?]+)/, data: (m) => resolveInvoice(m[1]) },
  { re: /\/api\/windcave\/env$/, data: () => ({ env: 'sec' }) },
  { re: /\/api\/subscription$/, data: () => SUBSCRIPTION },
  { re: /\/api\/billing\/card$/, data: () => ({ last4: '4242', brand: 'Visa', expiry: '08/28' }) },
  { re: /\/api\/push\/capabilities$/, data: () => ({ webPush: { available: false }, nativePush: { available: false } }) },
  { re: /\/api\/push\/status$/, data: () => ({ nativeSubscribed: false, subscribed: false }) },
];

const STOCK = [
  { id: 1, merchantId: MERCHANT_ID, name: 'Flat White', cost: '5.50', emoji: '☕', isActive: true },
  { id: 2, merchantId: MERCHANT_ID, name: 'Eggs Benedict', cost: '22.00', emoji: '🍳', isActive: true },
  { id: 3, merchantId: MERCHANT_ID, name: 'Avocado Smash', cost: '19.50', emoji: '🥑', isActive: true },
  { id: 4, merchantId: MERCHANT_ID, name: 'Berry Smoothie', cost: '11.00', emoji: '🥤', isActive: true },
  { id: 5, merchantId: MERCHANT_ID, name: 'Caramel Slice', cost: '6.50', emoji: '🍰', isActive: true },
];

